"""Private object storage. Object keys are generated by the application, never users."""

import os
import re
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol


@dataclass(frozen=True)
class ObjectInfo:
    size: int


class Storage(Protocol):
    def put(self, key: str, data: bytes) -> None: ...
    def read(self, key: str) -> bytes: ...
    def head(self, key: str) -> ObjectInfo: ...
    def delete(self, key: str) -> None: ...


class LocalStorage:
    """Atomic local writes into a private directory that is never mounted as static files."""

    def __init__(self, root: str | Path):
        root = Path(root).absolute()
        if root.is_symlink():
            raise ValueError("storage_root_symlink")
        root.mkdir(parents=True, exist_ok=True)
        self.root = root.resolve()

    def _path(self, key: str) -> Path:
        if not re.fullmatch(r"[a-zA-Z0-9_-]+(?:/[a-zA-Z0-9_.-]+)+", key):
            raise ValueError("invalid_object_key")
        parts = key.split("/")
        if any(part in {".", ".."} for part in parts):
            raise ValueError("invalid_object_key")
        target = self.root.joinpath(*parts)
        current = self.root
        for part in parts:
            current = current / part
            if current.is_symlink():
                raise ValueError("object_path_symlink")
        if not target.resolve().is_relative_to(self.root):
            raise ValueError("object_path_outside_storage")
        return target

    def put(self, key: str, data: bytes) -> None:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        # A temp file in the same directory enables an atomic rename on Windows too.
        temp_name = None
        try:
            with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as stream:
                temp_name = stream.name
                stream.write(data)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temp_name, path)
        finally:
            if temp_name and os.path.exists(temp_name):
                os.unlink(temp_name)

    def read(self, key: str) -> bytes:
        return self._path(key).read_bytes()

    def head(self, key: str) -> ObjectInfo:
        return ObjectInfo(size=self._path(key).stat().st_size)

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)
